function TimezoneOptions() {
  const { query } = useSelectSearch();
  const rows = useMemo(() => filterTimezones(query), [query]);

  return (
    <FlashList
      data={rows}
      estimatedItemSize={44}
      renderItem={({ item }) => <Select.Item value={item.id} label={item.name} />}
    />
  );
}

